1	//! Tests for Innistrad Tier 10 cards with activated abilities:
2	//! Manor Skeleton, Kessig Wolf, Feral Ridgewolf, Darkthicket Wolf,
3	//! Lantern Spirit, Avacynian Priest.
4	
5	mod common;
6	
7	use common::*;
8	use mtg_engine::actions::{Action, Target};
9	use mtg_engine::cards::CardRegistry;
10	use mtg_engine::engine;
11	use mtg_engine::sba::check_state_based_actions_with_registry;
12	use mtg_engine::types::*;
13	
14	fn registry() -> CardRegistry {
15	    CardRegistry::with_all_cards()
16	}
17	
18	// ══════════════════════════════════════════════════════════════════
19	// Manor Skeleton — {1}{B} 1/1 Skeleton, Haste, {1}{B}: Regenerate
20	// ══════════════════════════════════════════════════════════════════
21	
22	#[test]
23	fn manor_skeleton_has_correct_stats() {
24	    let reg = registry();
25	    let id = reg.get_id_by_name("Manor Skeleton").unwrap();
26	    let data = reg.card_data(id).unwrap();
27	    assert_eq!(data.power, Some(1));
28	    assert_eq!(data.toughness, Some(1));
29	    assert!(data.keywords.contains(&Keyword::Haste));
30	    assert!(data.subtypes.contains(&"Skeleton".to_string()));
31	}
32	
33	#[test]
34	fn manor_skeleton_regenerate_ability() {
35	    let reg = registry();
36	    let mut state = game_at_step(Step::PrecombatMain, P0);
37	
38	    let skeleton = named_creature(&mut state, &reg, "Manor Skeleton", P0);
39	
40	    // Add mana to pay {1}{B} for regenerate.
41	    state.get_player_mut(P0).mana_pool.add(ManaType::Colorless, 1);
42	    state.get_player_mut(P0).mana_pool.add(ManaType::Black, 1);
43	
44	    let legal = engine::legal_actions(&state, &reg);
45	    let activate = legal.actions.iter().find(|a| matches!(a, Action::ActivateAbility { .. }));
46	    assert!(activate.is_some(), "Should be able to activate regenerate ability");
47	
48	    state = engine::submit_action(&state, activate.unwrap(), &reg);
49	    assert_eq!(state.get_object(skeleton).unwrap().regeneration_shields, 1,
50	        "Activating should add a regeneration shield");
51	}
52	
53	#[test]
54	fn manor_skeleton_regeneration_saves_from_lethal() {
55	    let reg = registry();
56	    let mut state = game_at_step(Step::PrecombatMain, P0);
57	
58	    let skeleton = named_creature(&mut state, &reg, "Manor Skeleton", P0);
59	
60	    // Activate regenerate.
61	    state.get_player_mut(P0).mana_pool.add(ManaType::Colorless, 1);
62	    state.get_player_mut(P0).mana_pool.add(ManaType::Black, 1);
63	    let legal = engine::legal_actions(&state, &reg);
64	    let activate = legal.actions.iter().find(|a| matches!(a, Action::ActivateAbility { .. })).unwrap().clone();
65	    state = engine::submit_action(&state, &activate, &reg);
66	
67	    // Deal lethal damage.
68	    state.get_object_mut(skeleton).unwrap().damage_marked = 1;
69	    check_state_based_actions_with_registry(&mut state, Some(&reg));
70	
71	    // Should survive via regeneration.
72	    assert_eq!(state.get_object(skeleton).unwrap().zone, Zone::Battlefield,
73	        "Manor Skeleton should survive via regeneration");
74	    assert_eq!(state.get_object(skeleton).unwrap().damage_marked, 0,
75	        "Damage should be cleared after regeneration");
76	}
77	
78	// ══════════════════════════════════════════════════════════════════
79	// Kessig Wolf — {2}{R} 3/1 Wolf, {1}{R}: gains first strike EOT
80	// ══════════════════════════════════════════════════════════════════
81	
82	#[test]
83	fn kessig_wolf_has_correct_stats() {
